def first_or(xs: list[int], default: int) -> int:
    """Return the first element of xs, or default if xs is empty."""
    if not xs:
        return default
    return xs[0]


def test_first_or_nonempty_returns_first() -> None:
    assert first_or([3, 1, 2], 0) == 3


def test_first_or_single_element() -> None:
    assert first_or([7], 0) == 7


def test_first_or_empty_returns_default() -> None:
    assert first_or([], 42) == 42


def test_first_or_empty_returns_negative_default() -> None:
    assert first_or([], -1) == -1


def test_first_or_ignores_default_when_nonempty() -> None:
    assert first_or([5, 5], 99) == 5
